(async () => {
  const markdown = process.env.MARKDOWN;
  if (!markdown) throw new Error('Missing MARKDOWN env var');
  globalThis.markdown = markdown;
})();

(async () => {
  const markdownItMod = await import('markdown-it');
  const markdownIt = markdownItMod.default || markdownItMod;
  const taskListsMod = await import('markdown-it-task-lists');
  const taskLists = taskListsMod.default || taskListsMod;
  const md = markdownIt();
  md.use(taskLists);
  const result = md.render(globalThis.markdown);
  globalThis.html = result;
})();
